"""Cypher queries for generating all relevant test data
in the format valid BEFORE the migration is to take place"""

# Test data for LATEST_FINAL relationship with unwanted properties
#
# WITH "
#   MATCH (root:TemplateParameterValueRoot {uid: 'NA'})-[rel]->(value:TemplateParameterValue) RETURN *
# " AS query
# CALL apoc.export.cypher.query(query, null, {stream: true, format: "plain",  cypherFormat: "updateAll"})
# YIELD cypherStatements, file, batches, source, format, nodes, relationships, time, rows, batchSize
# RETURN cypherStatements;
TEST_DATA_UNWANTED_VERSIONING_PROPERTIES = """
CREATE CONSTRAINT UNIQUE_IMPORT_NAME FOR (node:`UNIQUE IMPORT LABEL`) REQUIRE (node.`UNIQUE IMPORT ID`) IS UNIQUE;
UNWIND [{uid:"NA", properties:{}}] AS row
MERGE (n:TemplateParameterValueRoot{uid: row.uid}) SET n += row.properties;
UNWIND [{_id:884132, properties:{name:"NA"}}] AS row
MERGE (n:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row._id}) SET n += row.properties SET n:TemplateParameterValue;
UNWIND [{start: {uid:"NA"}, end: {_id:884132}, properties:{}}] AS row
MATCH (start:TemplateParameterValueRoot{uid: row.start.uid})
MATCH (end:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row.end._id})
MERGE (start)-[r:LATEST]->(end) SET r += row.properties;
UNWIND [{start: {uid:"NA"}, end: {_id:884132}, properties:{}}] AS row
MATCH (start:TemplateParameterValueRoot{uid: row.start.uid})
MATCH (end:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row.end._id})
MERGE (start)-[r:LATEST_FINAL]->(end) SET r += row.properties;
UNWIND [{start: {uid:"NA"}, end: {_id:884132}, properties:{end_date:datetime('2023-09-26T14:33:16.368Z'), change_description:"Initial version", version:"1.0", user_initials:"Import-procedure", start_date:datetime('2023-09-26T14:33:16.368Z'), status:"Final"}}] AS row
MATCH (start:TemplateParameterValueRoot{uid: row.start.uid})
MATCH (end:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row.end._id})
MERGE (start)-[r:HAS_VERSION]->(end) SET r += row.properties
MERGE (start)-[rf:LATEST_FINAL]->(end) SET rf += row.properties;
MATCH (n:`UNIQUE IMPORT LABEL`)  WITH n LIMIT 20000 REMOVE n:`UNIQUE IMPORT LABEL` REMOVE n.`UNIQUE IMPORT ID`;
DROP CONSTRAINT UNIQUE_IMPORT_NAME;
"""

